INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(39400, 0, 394, 0, 0, 13, 'Grizzly Hills', 'The Grizzly Hills roll north of the Howling Fjord and east of the Dragonblight, a land of towering pine forest, clear rivers and snowy heights, rich in lumber, ore and game. Both the Alliance and the Horde want all of it. The Westfall Brigade and the woodsmen of Amberpine Lodge face the Horde''s Conquest Hold and its taunka allies at Camp Oneqwah, and the two sides fight over the abandoned Venture Company logging sites and the port of Venture Bay while each looks for a road north. In the northwest the Drakkari trolls of Drak''Tharon Keep are dying to the Scourge. Iron dwarves hold the eastern coast and the snowy southeast, while stone giants and earthen besiege their ancient capital of Thor Modan. At the heart of the hills lie the shattered remains of Vordrassil, a world tree the druids of old cut down, and around them the once peaceful furbolgs are at war. Trappers work the forests from scattered posts, and Dragonflayer vrykul muster at Voldrune near the southern coast.', 'quests 12468, 12412 (lumber, ore, water, game; the Alliance to be crushed in the hills); quests 12170, 12444 (Venture Company gone, its logging sites up for grabs); quests 12109, 12208, 12210, 12511 (each side seeks a way north); quest 12073 (iron dwarves hold the eastern coast; Thor Modan besieged by stone giants); quests 11982, 11981 (Kurun, giants and earthen besiege Thor Modan); quests 12207, 12219, 12229 (Vordrassil; furbolgs peaceful for thousands of years); zone_areas: Diseased and Slaughtered Drakkari at Zeb''Halak, Famished Scourge Troll around Drak''Tharon; quest 12222 (Dragonflayers muster at Voldrune near the southern coast); subzone list (trading posts)'),
(39401, 1, 394, 1, 0, 13, 'Amberpine Lodge', 'Amberpine Lodge stands in the western hills, a remote Alliance lodge long used by hunters and woodsmen. With the war, the military has taken charge, and Lieutenant Dumont commands from its halls. The lodge is short of food: a Horde raid on its storehouse left supplies dangerously low, so Master Woodsman Anderhol sends hunters after stag and grizzly and grumbles that the local worgs compete for the same game. Hierophant Thayreen, a druid who says her ancestors planted the world tree Vordrassil, studies the taint its remains left in the earth, and Woodsman Drake keeps watch on the Dragonflayers of Voldrune to the south.', 'npc_text 12955 (Dumont: lodge maintained for a while, used by hunters and woodsmen, military in charge now); quests 12212, 12215, 12216 descriptions (Horde raid on the storehouse; worgs compete for game; grizzlies); quest 12219 description (Thayreen: my ancestors once planted Vordrassil); quests 12222, 12223 descriptions (Drake: Voldrune to the south); quest 12511 description (Amberpine Lodge in western Grizzly Hills); zone_areas 4204'),
(39402, 1, 394, 2, 0, 13, 'Conquest Hold', 'Conquest Hold is the stronghold of the Horde''s Warsong Offensive in the western Grizzly Hills, raised to claim the region''s lumber, ore and water for the Horde''s war machine. Conqueror Krenna commands it with an iron hand, and her sister Gorgonna stands close by. Sergeant Nazgrim is set against the vrykul of Voldrune, Windseer Grayhorn warns that the beauty of these hills belies a great darkness below, and Hidetrader Jun''ik struggles to outfit a whole regiment in worg hides. Beside the hold lies the Conquest Pit, where the goblin Grennix Shivwiggle stages fights for a crowd of spectators. Krenna has outlawed pit-fighting for her enlisted soldiers, so the bouts are fought by free agents, prisoners and caged beasts.', 'FactionTemplate 1979 / Faction 1085 Warsong Offensive (the hold''s soldiers); quest 12468 description (lumber, ore, water; the Horde a war machine); quest 12451 description (Conquest Hold being built); quest 12424 description (my sister Gorgonna); npc_text 12824 (Nazgrim); npc_text 12773 (Grayhorn); quest 12175 description (Jun''ik outfitting the regiment); quests 12427, 12429 descriptions (pit-fighting outlawed for enlisted combatants; prisoners and caged beasts); creature_text 27719 (Grennix announcing fights); zone_areas 4206, 4248'),
(39403, 1, 394, 3, 0, 13, 'Venture Bay', 'Venture Bay is a port on the southwestern coast of the hills, with a sawmill, bunkhouse and stables built by the Venture Company and a lighthouse on the point. The goblins gave up their operations soon after the armies arrived, and only stragglers still hide in the buildings while evacuees wait for their ship. Now the Westfall Brigade and the berserkers of Conquest Hold fight over the port, its docks and its lighthouse. Each side tries to sink the other''s lumber ships by riding goblin torpedoes into them, and refurbished shredders from the logging grounds are thrown into the battle.', 'quests 12170, 12444 descriptions (Venture Company abandoned operations; sites up for grabs); quests 12323, 12324 descriptions (stragglers in the bunkhouse, sawmill and stables; make for their ship); quests 12314, 12315, 12316, 12317 descriptions (Westfall Brigade and Conquest Hold berserkers contest the port); quests 12432, 12437 descriptions (lighthouse; torpedoes against the lumber ships); quests 12244, 12270 descriptions (refurbished shredders sent to Venture Bay); zone_areas 4242 (Venture Co. Straggler, Evacuee, Westfall Brigade Marine, Conquest Hold Berserker, Alliance Lumberboat, Refurbished Shredder)'),
(39404, 1, 394, 4, 0, 13, 'Voldrune', 'Voldrune is a Dragonflayer vrykul village near the southern coast, ruled by Thane Torvald Eriksson from the tops of its towers. His huscarls are mustering for war, and his flamebinders craft flame-imbued talismans that let the village''s mightiest warriors master savage, half-trained proto-drakes. The thane''s own favorite, an unruly proto-drake called Flamebringer, is kept bound in chains on the village''s western side. Amberpine Lodge and Conquest Hold, their forces spread thin fighting each other, both fear the Dragonflayers will strike while their backs are turned.', 'quests 12222, 12223 descriptions (Alliance: flamebinders, talismans, huscarls preparing for war); quests 12256, 12257 descriptions (Horde: half-trained proto-drakes; thane cannot field a large army, but forces spread thin); quests 12255, 12259 descriptions (Flamebringer chained in the west; thane on the towers); npc_text 12811 (Flamebringer); zone_areas 4207'),
(39405, 1, 394, 5, 0, 13, 'Silverbrook', 'Silverbrook is a village of trappers in the northwest of the hills, hardy folk who know the lay of the land better than any soldier. Its villagers and hunters are friendly to the Alliance and hostile to the Horde, whose marauders from Conquest Hold prowl the Silverbrook Hills just outside town. Envoy Ducal has come from Amberpine Lodge to win the trappers over. The hunter Sergei says no one is a real hunter who does not wear his prey''s skin, and Katja wants the wolfsbane that keeps sprouting near the village uprooted, calling it a weed that ruins their crops.', 'quest 12295 description and reward text (Ducal sent a week ago; hardy people who know the land); quest 12413 description (Silverbrook, main town in northern Grizzly Hills); quest 12299 description (Conquest Hold marauders just outside the town); quest 12300 description (Sergei: wear your prey''s skin); quest 12307 description (Katja: wolfsbane destroys our crops); FactionTemplate 2032 (Grizzly Hills Trapper: friendly to the Alliance, hostile to the Horde); zone_areas 4199, 4251'),
(39406, 1, 394, 6, 0, 13, 'Granite Springs', 'Granite Springs is a camp of bounty hunters in the shadow of Drak''Tharon Keep, due south of Zeb''Halak. Samir pays well for ice trolls taken alive, and both Conquest Hold and Amberpine Lodge have hired his gang to supply them. Budd, who has been of little use to them since their stay in the Ghostlands, wears a mask, and something about his condition lets him mingle with the trolls. Mack Fearsen, rarely sober, burns the corpses of Scourge trolls before they rise again, Prigmon wraps the carcasses for the fire, and in a cage sits a Drakkari prisoner named Drakuru.', 'quest 12208 description (Thurkin: gang contracted to deliver captured trolls; Samir due south of Zeb''Halak); quest 12210 description (Dumont: gang of thugs to capture and deliver live trolls); npc_text 12966 (Samir: paying well for live trolls); quest 11984 description (Budd, Ghostlands, mingles with the trolls); npc_text 12617 (Budd''s mask); quest 12029 description (Mack burns the corpses; troll keep up north); quest 12484 description (Prigmon wrapping troll carcasses); quest 11989 description and npc_text 12998 (Drakuru in his cage); zone_areas 4208'),
(39407, 1, 394, 7, 0, 13, 'Zeb''Halak', 'Zeb''Halak is a Drakkari ziggurat north of Granite Springs, and its trolls are dying. Diseased Drakkari fill its terraces, Scourge deathspeakers and corpserenders walk among them, and the bodies of slaughtered trolls lie along the river where threshers swim. Atop the ziggurat stands a great stone head with ruby eyes. In a hut at Zim''bo''s Hideout the warlord Zim''bo holds out, swearing when cornered that Drak''Tharon must be liberated.', 'zone_areas 4209 (Diseased Drakkari 26457, Slaughtered Drakkari 27613, Scourge Deathspeaker 27615, Scourge Corpserender 26461, River Thresher 27617); quest 12007 description (ziggurat north of Granite Springs; stone head with ruby eyes; Zim''bo hiding in a hut); creature_text 26544 (Zim''bo: For Drak''Tharon! Da keep must be liberated!); zone_areas 4475 (Warlord Zim''bo)'),
(39408, 1, 394, 8, 0, 13, 'Blue Sky Logging Grounds', 'The Blue Sky Logging Grounds were a Venture Company timber works, a sawmill and timber buildings beside a river choked with broken trees. The goblins left soon after the armies arrived, and the Westfall Brigade and Conquest Hold have fought over the site ever since, with heavy losses on both sides. The dead and wounded of both armies lie across the field while their healers struggle to keep up, and both sides haul away the broken-down shredders the goblins left behind. The Blackriver Logging Camp, smallest of the three logging sites in the hills, is fought over in the same way.', 'quest 12042 description (chamber near a river of broken trees); quest 12268 description (down around the sawmill); quests 12284, 12289 descriptions (heavy casualties on both sides; resources vital); quests 12288, 12296 descriptions (too many wounded); quests 12244, 12270 descriptions (broken-down shredders); quests 12170, 12444 descriptions (Venture Company gone; Blackriver the smallest of the three logging sites); zone_areas 4222, 4217'),
(39409, 1, 394, 9, 0, 13, 'The Remains of Vordrassil', 'Long ago powerful druids planted a tree in the heart of the Grizzly Hills, meant to become a world tree. It was called Vordrassil, and once it was fully grown the druids decided, for reasons long forgotten, that it had to be destroyed. Its giant trunk splintered where it struck the ground, at the three places now called Vordrassil''s Heart, Vordrassil''s Tears and Vordrassil''s Limb, west of Grizzlemaw. Entropic oozes crawl where the tree touched the earth, and those who listen to the land say it still cries out in pain there.', 'quest 12207 description (druids planted it; to be a world tree; the earth''s cries where the remains fell; ooze); quest 12219 description (reasons long forgotten; trunk splintered at three locations); quest 12220 description (west of Grizzlemaw); zone_areas 4200, 4202, 4203 (Entropic Ooze 26366)'),
(39410, 1, 394, 10, 0, 13, 'Grizzlemaw', 'Grizzlemaw is the furbolg city at the center of the Grizzly Hills, raised within the hollow of Vordrassil''s old trunk. For thousands of years the furbolgs of the region lived in peace, but now their tribes are locked in a deadly war: Frostpaw and Redfang fight through Grizzlemaw itself, the Frostpaw also hold the Rage Fang Shrine and the Redfang the Heart''s Blood Shrine, and seeds of Vordrassil lie scattered through the city. Ursoc''s children dwell by the shrines. Orsonn says he once roamed the hills but is now doomed to stay in his cave, and Kodian watches over what she calls a once sacred shrine.', 'quest 12248 description (the sapling in the middle of Grizzlemaw, inside Vordrassil''s old trunk); quests 12229, 12231, 12247 descriptions (peaceful for thousands of years; deadly tribal war; Ursoc''s children at the shrines); quests 12242, 12250 descriptions (Vordrassil''s seeds at Grizzlemaw); npc_text 12793 (Orsonn), 12797 (Kodian); zone_areas 395 (Frostpaw 26357, 26428; Redfang 26356, 26436; Vordrassil''s Seed 188691), 4215 (Frostpaw, Orsonn), 4218 (Redfang, Grumbald One-Eye)'),
(39411, 1, 394, 11, 0, 13, 'Westfall Brigade Encampment', 'The Westfall Brigade Encampment stands in the north of the hills, southwest of Thor Modan. Captain Gryan Stoutmantle''s soldiers have come a long way from Westfall in search of a road north, and here they have their hands full, with the Horde to the west and the iron dwarves to the east. Most of the brigade''s horsemen were left at the fight for Venture Bay, so Squire Percy is taming wild mustangs to replace them. Brugar Stoneshear and Torthen Deepdig of the Explorers'' League share the camp.', 'quest 12109 description (sent east to look for a path into the northern territories; secure strategic resource points); quest 12158 description (Horde on the west, iron dwarves to the east); quest 12002 description (Thor Modan just to the northeast); quest 12414 description (horsemen left at Venture Bay; mustangs); npc_text 13512 (Gryan: a long way from Westfall); zone_areas 4159 (Brugar 26226, Torthen 26361, Squire Percy 26377)'),
(39412, 1, 394, 12, 0, 13, 'Thor Modan', 'Thor Modan is the ancient capital of the iron dwarves, laid open since stone giants tore the land asunder thousands of years ago and collapsed part of the city. The sons of iron want it back, and they are besieged. From the hill above, the stone giant Kurun and his giants hurl boulders into the trench to bury the diggers, earthen warriors battle runic golems in the plaza, and Forgemaster Damrath urges his constructs to defend the capital for the thane and for Loken. In the Boulder Hills to the north, iron rune-shapers bind stone giants with runes and turn them on their own kin. Torn journal pages litter the battlefield.', 'quest 11982 description and reward text (stone giants tore the land asunder; iron dwarves reclaim their capital; boulders into the trench); quests 11981, 12074 (Kurun on the hill commanding giants and earthen); creature_text 26334 (Forgemaster Damrath yells: defend the capital; For the thane! For Loken!); quest 12070 description (giants enthralled by runes; Boulder Hills to the north); quest 11986 description (journal pages litter the battlefield); zone_areas 4221, 4214'),
(39413, 1, 394, 13, 0, 13, 'Camp Oneqwah', 'Camp Oneqwah is a taunka camp in the easternmost reaches of the Grizzly Hills, beyond Grizzlemaw, and its people are allies of the Horde. Their chieftain is Tormak the Scarred, and Sage Paluna answers to him. Scout Vor''takh came from Conquest Hold while the hold was still being built, to make contact with the taunka, and he holds that with their help Northrend will belong to the Horde. Wind riders and stables serve the camp, and its warriors keep a wary eye on the iron dwarves who hold the eastern coast and on the Westfall Brigade camped to the north.', 'quest 12451 description (Vor''takh sent to make contact with our taunka allies; easternmost part, beyond Grizzlemaw); npc_text 14245 (Vor''takh); creature_template 27221 subname Camp Oneqwah Chieftain; quests 12054, 12058 (Sage Paluna and the chieftain); quest 12073 description (iron dwarves hold the eastern coast); quest 12415 description (Westfall Brigade camped far to the north); zone_areas 4211 (Soulok Stormfury stable master, Makki Wintergale wind rider master)'),
(39414, 1, 394, 14, 0, 13, 'Drakil''jin Ruins', 'The Drakil''jin Ruins are haunted Drakkari ruins on the eastern coast of the hills, raised around a crypt. Drakkari oracles and protectors guard the grounds under Drak''aguul, great gongs stand outside, and within, long-dead Drakkari warmongers and soothsayers walk again among guardian serpents. The trolls keep prisoners in cages here, among them a man named Harrison Jones. Nearby, at Harkor''s Camp, the troll-hating Harkor waits by his fire for an associate, and the mystic Kraz listens to the voices crying out from the ruins.', 'quest 12190 description (Harkor camped on the eastern coast near the haunted ruins); quests 12114, 12116, 12120, 12121 descriptions (oracles and protectors; crypt; Drak''aguul; gongs); zone_areas 4216 (Drakkari Oracle 26795, Protector 26797, Ancient Drakkari Warmonger 26811, Soothsayer 26812, Guardian Serpent 26806, Gong Bunny); npc_text 12694 and gameobject 188465 Harrison''s Cage; quests 12113, 12114 descriptions (Harkor waiting on an associate; hates trolls); zone_areas 4266'),
(39415, 1, 394, 15, 0, 13, 'Eastwind Shore', 'The Eastwind Shore runs along the eastern coast of the Grizzly Hills, where longhoof grazers roam above the sea. The iron dwarves have made it a road of slavery. Iron rune-weavers man great runes of compulsion along the coast: stone giants are summoned from the earth, bound with runes and sent marching north along the Path of Iron to the battlefields of the north. On a cluster of small islands off the central shore, the Ruins of Tethys, the stone giant Gavrock searches for a way to free his runed brothers.', 'quest 12093 description (summoning brothers from the earth, binding them with runes; runes of compulsion along the Eastwind Shore send enslaved giants north); quest 12081 description (Gavrock at the Ruins of Tethys, islands off the central Eastwind Shore); quests 12094, 12099 descriptions (Path of Iron; runed giants walking north along the shore); zone_areas 4212 (Longhoof Grazer, Iron Rune-Weaver, Runed Giant, Directional Rune), 4250 (Gavrock)'),
(39416, 1, 394, 16, 0, 13, 'Dun Argol', 'Dun Argol is the iron dwarves'' stronghold in the snowy southeast of the hills, at the southern end of the Eastwind Shore. Its foundries work day and night: iron rune-smiths turn out war golems, lightning sentries patrol its perimeter, and a runic power core in the great hall at the top drives the whole works. Iron Thane Furyhammer oversees production with his guardian construct, the Anvil, at his side, and captives sit in its cages. Nearby, at Prospector''s Point, Raegar Breakbrow of the Explorers'' League watches the iron dwarves prepare for war.', 'quest 12128 description (Raegar''s post near Dun Argol at the southern end of the Eastwind Shore); quests 12165, 12196 descriptions (snowy regions to the southeast; foundries working day and night); quests 12129, 12138, 12154 descriptions (rune-smiths and war golems; lightning sentries; power core in the hall at the top); quest 12153 description (Furyhammer and the Anvil); quest 12128 reward text (preparing for war); zone_areas 4220 (Dun Argol Cage 188554), 4229'),
(39417, 1, 394, 17, 0, 13, 'Solstice Village', 'Solstice Village is a settlement in the eastern hills, beyond the White Pine Trading Post, and it has turned its back on the world. Its hunters, armed with bows, stings and fire traps, shoot any stranger on sight, and its people have given themselves to the wolfcult, whose initiates walk openly among them. Duskhowl prowlers roam the woods around it, and over the hill lies Duskhowl Den, a wolf den in the rocks.', 'quest 12329 description (White Pine Trading Post, on the way to Solstice Village); quest 12134 description (the wolfcult in Solstice Village); zone_areas 4205 (Solstice Hunter 26389, Wolfcult Initiate 26416, Duskhowl Prowler 27408); smart_scripts 26389 (Shoot, Multi-Shot, Scorpid and Serpent Sting, Immolation Trap); creature_text 26971 (the wolf den on the other side of the mountain)'),
(39418, 1, 394, 18, 0, 13, 'Bloodmoon Isle', 'Bloodmoon Isle lies just off the eastern coast of the hills, a stronghold of the Bloodmoon worgen and the cultists who serve beside them. Selas and Varlam, who is called the Hand of Arugal, hold the island, and on it rises Shadowfang Tower, where the great worg Goremaw keeps guard over a shade that bears Arugal''s name, channeling some dark magic.', 'quest 12164 description (Bloodmoon Isle just off the coast, east of White Pine); zone_areas 4244 (Bloodmoon Worgen 27020, Bloodmoon Cultist 27024, Selas 27580, Varlam 27579 Hand of Arugal), 4245 (Shade of Arugal 27018, Goremaw 27578, a beast); smart_scripts 27018 (casts Arugal Channel out of combat)'),
(39419, 2, 394, 1, 2, 13, 'Conqueror Krenna', 'Conqueror Krenna commands Conquest Hold, and word in the Horde is that she is aggressive even for an orc. To her the Horde is a magnificent war machine and every soldier a cog in it. Her charge is to fuel that machine with the lumber, ore and water of the Grizzly Hills before the Alliance can, and she means to see the Alliance crushed here. Past deeds earn nothing from her: respect comes only from following her orders without question. Her regiment is to be outfitted in worg hides by the end of the week, and her hidetrader fears being made to wrestle bears in the pit if it is not.', 'quest 12487 description (aggressive even for an orc); quest 12468 description (war machine, cog, lumber, ore, water); quest 12412 description (the Alliance will be crushed in the Grizzly Hills); npc_text 12906 (respect only by following orders); quest 12175 description (deadline; wrestling bears in the pit)'),
(39420, 2, 394, 2, 1, 13, 'Lieutenant Dumont', 'Lieutenant Dumont commands the Alliance at Amberpine Lodge, where the military has taken over from the hunters and woodsmen. He sees the war in the hills as a deadlock, the two sides about evenly matched, and he looks for any edge he can find, from the goodwill of the local trappers to intelligence wrung from captured trolls. Drak''Tharon Keep, he holds, is the most direct route to Zul''Drak and must be taken to secure safe passage for the Alliance. Until he has the numbers for an assault, he has conscripted a gang of thugs to deliver live ice trolls for interrogation.', 'npc_text 12955; quest 12292 description (deadlock; the trappers'' help); quest 12210 description (Drak''Tharon the most direct route to Zul''Drak; gang of thugs; live trolls for interrogation)'),
(39421, 2, 394, 3, 0, 13, 'Sasha', 'Sasha is the elder daughter of Mikhail, a man of Silverbrook who sent her away from the village when the wolfcult began to win his neighbors over. The cult''s monsters, she says, killed her father and carried off her little sister, and they are going to pay for it. An outcast from her own people, she hunts them from the White Pine Trading Post on the road to Solstice Village, and once her sister is safe she means to find whoever is behind it all.', 'quest 12105 description (Mikhail sent his daughter Sasha away); quest 12422 description (trapper outcast; Mikhail''s older daughter); npc_text 13445 (monsters killed my father and kidnapped my sister); quest 12302 description (my name''s Sasha; my people have changed); quest 12329 description (White Pine Trading Post, on the way to Solstice Village); quest 12330 description (find the person behind all this once we save my sister)'),
(39422, 2, 394, 4, 0, 13, 'Arugal', 'Arugal was the sorcerer of Dalaran who called the worgen into Silverpine Forest, and he is said to have died years ago. Yet in the Grizzly Hills his name is heard again. On Bloodmoon Isle, off the eastern coast, a shade that bears his name keeps to Shadowfang Tower, guarded by the great worg Goremaw and served by the Bloodmoon worgen and their cultists, and by Varlam, who is called the Hand of Arugal.', 'warcraft.wiki.gg/wiki/Arugal (Dalaran sorcerer who summoned the worgen to Silverpine); quest 12160 reward text (Arugal''s been dead for years); zone_areas 4244, 4245 (Shade of Arugal 27018, Varlam Hand of Arugal, Bloodmoon worgen and cultists); quest 12164 description; creature_text 26971 group 7 (nothing compares to what Arugal can do to us); quest 12160 description (his wolfcult)'),
(39423, 2, 394, 5, 0, 13, 'Ruuna the Blind', 'Ruuna the Blind keeps a lonely camp near Vordrassil Pass. They say she speaks to the dead and has visions of the past and the future, and those with questions no one else can answer come to her, Alliance and Horde alike. She asks no gold for her readings, only that seekers gather the reagents her potions require, for she can foresee that much hinges on what they learn. She warns each of them that the answers she gives might not be to their liking.', 'quest 12161 description (speaks to the dead, visions of past and future); quest 12425 description (a fortune teller); quest 12328 description (no gold; gossamer dust reagent; much hinges on what you learn); quests 12161 and 12425 reward text (answers might not be to your liking)'),
(39424, 2, 394, 6, 0, 13, 'Hugh Glass', 'Hugh Glass is a trapper who keeps the Redwood Trading Post with a great bear he calls Griselda. His moonshine is the finest in the forest, and he is not right in the head. He greets strangers as his old friend Limpy Joe, and he mutters to Griselda that the two of them escaped the monsters who got Limpy Joe and Flannel McGee, that they are hunters and nothing like those wolfmen, and that she must keep an eye out so the monsters never get them.', 'quest 11998 description (finest moonshine; not right in the head); npc_text 12752 (Limpy Joe, it''s you); creature_text 26484 groups 0 and 9 (group 9 said out of combat every 60 to 90 seconds, SmartAI 26484); zone_areas 4231 (Griselda 26494, a beast)'),
(39425, 2, 394, 7, 0, 13, 'Harrison Jones', 'Harrison Jones is a prisoner of the Drakkari at Drakil''jin, held in a cage among the ruins. He is far from cowed. He calls newcomers kid, warns them to clear out before they find themselves in a cage of their own, and lets them know that he is about to make a break for it: anyone who sticks with him, he promises, will get out of there too.', 'npc_text 12694; quest 12082 description; gameobject 188465 Harrison''s Cage'),
(39426, 3, 394, 1, 0, 13, 'The Wolfcult', 'A journal found in the hills was written by Mikhail, a man of Silverbrook, the trappers'' village in the northwest. Its writer was uneasy: fearing for his family, he sent a daughter away from the village, and then the entries stop. Whatever became of Mikhail, the journal hints that there is more going on in Silverbrook than meets the eye. Elsewhere in the hills, at Solstice Village, the people have given themselves to the wolfcult, whose initiates walk openly among them.', 'quest 12105 description (Alliance: Mikhail of Silverbrook; sent his daughter away; entries end); quest 12423 description (Horde: journal by Mikhail of Silverbrook); quest 12424 reward text (Horde: feared for his daughters'' lives, sent them away; more than meets the eye); zone_areas 4205 (Wolfcult Initiate 26416 in Solstice Village)'),
(39427, 3, 394, 2, 0, 13, 'The Trappers of Silverbrook', 'The war between the Alliance and the Horde in the Grizzly Hills has reached a deadlock, the two sides so evenly matched that any edge could decide it. The trappers of Silverbrook could be that edge. They are hardy people who know the land as no soldier does, and they lean toward the Alliance: Lieutenant Dumont has sent an envoy to win them over, and they have asked the Alliance''s help in recovering something the Horde took from them. At Conquest Hold, Conqueror Krenna wants them slaughtered before they can join her enemies.', 'quest 12292 description (deadlock; trappers'' relic taken by the Horde); quest 12295 description (Ducal sent to Silverbrook); quest 12412 description (trappers seek to join the Alliance; slaughter them first); FactionTemplate 2032 (friendly to the Alliance, hostile to the Horde)'),
(39428, 3, 394, 3, 0, 13, 'The Taint of Vordrassil', 'Hierophant Thayreen of Amberpine Lodge and Windseer Grayhorn of Conquest Hold, enemies in every other matter, have turned to the same wound in the land. Where the remains of the failed world tree Vordrassil fell, a foul, unnatural ooze crawls across the ground, and both druids want samples of it to learn what poisoned the earth and how it can be healed. No one remembers why the druids of old, having raised the tree to its full height, decided that it had to be destroyed, and both mean to find out.', 'quest 12219 description (Thayreen); quest 12207 description (Grayhorn: the earth has spoken to me); quest 12220 description (we must first find out what caused Vordrassil to fail)'),
(39429, 3, 394, 4, 0, 13, 'Drakuru''s Bargain', 'In a cage at Granite Springs sits Drakuru, a Drakkari troll who boasts that he has shrunk more heads than he can remember and admits he would add one more if he were not behind bars. The bounty hunters who hold him sell captured trolls to the highest bidder. Things being as they are, Drakuru proposes putting differences aside for a time: he cuts his palm on one of his own tusks, reaches the bleeding hand through the bars and offers a truce sealed in blood. Drakuru knows things, he says, things that will aid in the struggle here.', 'quest 11989 description and reward text; quest 11984 description (selling trolls to the highest bidder); npc_text 12998, 12999, 13001'),
(39430, 3, 394, 5, 0, 13, 'The Spirits of Drakil''jin', 'Kraz, a mystic camped with Harkor beside the Drakil''jin Ruins, has strained for many years to hear the spirits and do their bidding. Lately many voices have been crying out to him from the ruins: the spirits of the Drakkari who came before, seeking a peace they cannot find on their own. To learn what holds them there, Kraz needs something that once belonged to them, brought up from the crypt beneath the ruins, where living Drakkari still stand guard.', 'quest 12116 description; zone_areas 4216 (Drakkari Oracle and Protector)'),
(39431, 3, 394, 6, 0, 13, 'The Iron Dwarves of Dun Argol', 'At Dun Argol, in the snowy south of the hills, the iron dwarves are preparing for war, and both the Alliance and the Horde are watching. Raegar Breakbrow of the Explorers'' League, whose research team has not returned, fears its giants, golems and lightning elementals could catch the Westfall Brigade by surprise. At Camp Oneqwah, a hunting party has brought in a wounded dwarf fleeing Dun Argol, and the Horde wants to know who drives the iron dwarves, who have fought the Horde everywhere with the name of Loken on their lips.', 'quest 12128 reward text (preparing for war; research team not returned); quest 12129 description (giants, golems, lightning elementals; Westfall Brigade taken by surprise); quest 12195 description (wounded dwarf fleeing Dun Argol); quest 12204 description (the name of Loken on their lips)'),
(39432, 3, 394, 7, 0, 13, 'Brann''s Journal', 'Amid the battle at Thor Modan lies a battered, mud-stained journal full of notes, diagrams and maps, and among its entries is the signature of Brann Bronzebeard. The back half of the book, which held the most recent entries, has been torn away, and its pages litter the battlefield, as if someone thought them important enough to destroy. Brann himself is nowhere to be seen, and whatever he discovered in Thor Modan cannot be known until the journal is whole again.', 'quest 11986 description (Alliance); quest 12026 description (Horde: someone thought the notes important enough to destroy)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(39401, 1, 0, 255, 'The Horde found the lodge''s hidden food stores through the eyes of the imperial eagles that soar above the trees, binding its sight to the unsuspecting birds to watch every move Amberpine made. By the lieutenant''s order the majestic eagles were hunted down, a somber task, but the lodge rests easier knowing the enemy''s eyes are no longer upon it.', 'quest 12217 description and reward text'),
(39402, 1, 0, 255, 'Krenna no longer gives the orders in Conquest Hold. Where the conqueror once stood with her guards, her sister Gorgonna now stands at the head of the hold, with legionnaires at her side.', 'spell_area 49416/49417 in 4206 around 12431; creature_addon auras 49414 (Krenna, Anthis, Sethyel, Gorgonna guid 117164) and 49415 (Gorgonna guid 29974 and two legionnaires at Krenna''s spot); quest 12431 reward text'),
(39404, 1, 0, 255, 'The thane''s own beast brought him down. With the flamebinders'' talismans in hand, Flamebringer was bent to a stranger''s will, and the proto-drake was turned against Torvald Eriksson atop his towers until the thane of Voldrune fell.', 'quests 12255 and 12259 descriptions and reward text'),
(39405, 1, 0, 255, 'Silverbrook''s welcome was a mask. Its trappers are worgen, and Envoy Ducal had already become one of them. Since their secret was carried out of the village, Silverbrook and the trappers of the posts beyond have turned their blades on the one who escaped with it.', 'quest 12308 reward text (Worgen); creature_text 27411 (Ducal is one of them now); spell_area 49640 in area 394 from 12308 rewarded; Spell.dbc 49640 Trapper Force Reaction (faction 1095, hostile)'),
(39409, 1, 0, 255, 'The hollow remains grew roots deep into the ground. An orb carried into the depths beneath each of the three sites came back tainted by a dark and overwhelming force, proof that something evil has soaked into the ground around Vordrassil''s remains, and the druids who read it mean to learn more.', 'quests 12220 and 12213 descriptions and reward text'),
(39411, 1, 0, 255, 'Captain Stoutmantle hoped to move troops quickly toward Icecrown through the tunnels beneath Thor Modan. The survey dashed that hope. Surveyor Orlond was found dead inside the city, and the last readings showed blocked, unstable tunnels, some unused for generations, that might collapse again even if they were dug out.', 'quest 11998 description (tunnels beneath Thor Modan to move forces to Icecrown); quest 12010 reward text (Orlond long dead); quest 12014 description and reward text'),
(39412, 1, 0, 255, 'The iron dwarves'' commander, Iron Thane Argrum, was hunted down inside the city, where the tunnels narrow too quickly for giants to follow. Kurun judged that his loss would break the remaining defenders, leaving the earthen to deal with the survivors.', 'quest 11985 description and reward text'),
(39415, 1, 0, 255, 'Gavrock found a way. With the runes silenced and a shard of his own stone charged at ancient markers on the ley lines, the shard''s power was loosed on the giants marching north, and some came back to their senses. Whether it will free them all is uncertain, but Gavrock believes his people are at last on the right path.', 'quests 12093, 12094, 12099 descriptions and reward text'),
(39417, 1, 0, 255, 'Sasha names it plainly: a curse that makes beasts out of people has taken Silverbrook and Solstice Village alike. Her father tried to warn them, but they listened to the wolfcult instead, and she judges them too far gone. Putting the hunters down, she says, is for their own sake, though it will not bring her father back.', 'quest 12134 description and reward text'),
(39419, 1, 0, 255, 'Jun''ik''s shortcut did not fool her. Short of worg hides, he dusted brown bear hides gray with coal and flour, and the bundle reached the conqueror smelling of flour. Krenna called it a complete insult to the Horde.', 'quests 12176, 12177 descriptions; quest 12178 reward text'),
(39419, 2, 0, 255, 'Krenna''s rule ended in her own pit. She accused her sister Gorgonna of going behind her back and neglecting her orders, and turned on her before the crowd. Gorgonna answered that she had used good judgment where Krenna showed none and would not watch her lead them into ruin. Krenna fell in the fight, and Gorgonna, kneeling, said she had freed her people from a tyrant but lost a sister.', 'quest 12431 description and reward text; creature_text 27727 groups 0-1, 27726 groups 0-3; smart_scripts 27727, 2772700, 2772600, 2772601'),
(39421, 1, 0, 255, 'With Tatjana taken alive as leverage, her husband Anatoly, the captive Sasha could not make talk, gave up where Anya was held: a wolf den over the hill, from which she was to be taken to Arugal. Swearing on her father''s memory to stand beside her helpers when they faced Arugal, Sasha went after her sister and found her in Duskhowl Den, frightened, saying the mean men had meant to carry her to Bloodmoon Isle and make her one of them.', 'quest 12330 description; creature_text 26971 groups 4-5, 26935 groups 3-8, 27646 groups 0-2; quest 12411 description and reward text'),
(39422, 1, 0, 255, 'On Bloodmoon Isle Arugal''s lieutenants Selas and Varlam and the worg Goremaw were cut down, and in Shadowfang Tower his shade was beaten, with Sasha at hand for the end. It was not enough to finish him, she judged, but one thing was certain: he would not be seen in these parts any longer.', 'quest 12164 description, objectives and reward text'),
(39423, 1, 0, 255, 'Ruuna believes in fate, not coincidence: on the day she lost her eyesight, she says, she was given the gift of clairvoyance. The vision her latest seeker was shown had been granted earlier that same day to a young woman named Sasha, and Ruuna sent the seeker east to find her at the White Pine Trading Post.', 'quest 12329 description and reward text'),
(39424, 1, 0, 255, 'Sent to catch salmon for Griselda, the visitor came back with the fish and broke the spell: this was not Limpy Joe at all. Hugh decided the stranger must have killed poor Joe, begged leave to feed Griselda one last meal before he too was done in, and settled on calling his guest an enigma, adding that enigmas and he do not get along.', 'quest 12279 description and reward text; creature_text 26484 groups 2-8 (smart_scripts 26484 event 1, actionlist 2648401)'),
(39425, 1, 0, 255, 'The break worked. Harrison led the way through the trolls'' ceremonial chamber, where he was to have been sacrificed, freed a woman caged there, and tried something meant to put an end to the place, puzzled when it did not work. A great serpent, Tecahuna, barred the way out; he groaned at the sight of a snake, fought through, and with a cheerful farewell was gone.', 'creature_text 26814 groups 0-9; smart_scripts 26814 and actionlists 2681400-2681404 (Adarrah''s cage, Tecahuna summoned); quest 12082 reward text'),
(39426, 1, 0, 255, 'Read in full, the journal tells how a shadow-worshipping group called the wolfcult came to Silverbrook. At first the villagers would have none of it, but sympathizers sprang up one by one, and Mikhail, unsettled, sent his daughter Sasha away while he tried to reason with his neighbors. His last entry speaks of a meeting of the town''s leaders about events at Hollowstone Mine.', 'quest 12105 description'),
(39426, 2, 0, 255, 'Dumont thought it worth a look, and Captain Stoutmantle let the mine be searched. It was full of Scourge. Its survivor, the miner Petrov, begged that his risen comrades be burned so they would stay down, and said Arugal had made an example of them because they would not join his wolfcult. Stoutmantle put it down to grief: Arugal, he said, had been dead for years, and he had seen the grave himself.', 'quest 12105 reward text; quests 12109, 12158 descriptions; quests 12159, 12160 descriptions and 12160 reward text'),
(39426, 3, 0, 255, 'Krenna wanted the journal burned, but her sister Gorgonna read it and would not let it go. A trapper outcast captured outside Silverbrook, due to be executed, matched the diary''s description of Mikhail''s elder daughter, so Gorgonna sent her a letter of amnesty, hoping she would lead the Horde to whoever controls the trappers. Freed, the young woman said only that monsters had killed her father and taken her sister.', 'quest 12424 description and reward text; quest 12422 description and reward text'),
(39426, 4, 0, 255, 'The trail led next to Ruuna the Blind, a seer who keeps a lonely camp near Vordrassil Pass. Those with questions no one else can answer seek her out, and what is happening in Silverbrook is just such a question.', 'quest 12161 description (Ruuna speaks to the dead); quest 12425 description (the former captive seen meeting a fortune teller)'),
(39427, 1, 0, 255, 'The trappers asked a favor first. The Horde had taken a relic of theirs, a plain-looking cedar chest held at the Evergreen Trading Post, and once it was back in their hands, the trapper Ivan, who nearly let slip what was inside, agreed to the pact. Dumont expected local woodsmen to be scouting for the king''s army in no time.', 'quests 12292, 12293, 12294 descriptions and reward text'),
(39427, 2, 0, 255, 'In Silverbrook the welcome seemed warm. Sergei sent his new ally to prove their mettle by skinning Sergeant Bonesnap, leader of the orcs raiding the town, but at Bonesnap''s camp the orcs'' captive, a trapper named Sasha, begged them to stop. Her people had changed, she warned. They were not good people anymore, and they meant to turn newcomers into what they had become. Trust no one, she said.', 'quest 12300 description and reward text; quest 12302 description'),
(39427, 3, 0, 255, 'At the northwestern end of Silverbrook a caged Alliance scout asked only one thing: had his rescuer been bitten? The trappers were not human, he said, and Envoy Ducal was one of them now. The two fled on Ducal''s horse with lamp oil against the fiends, who hate fire, and at Amberpine Lodge Dumont named the truth: worgen.', 'quest 12308 description and reward text; creature_text 27411 groups 0-4'),
(39427, 4, 0, 255, 'At the Forest''s Edge Post the Silverbrook hunters and their leader, Vladek, were cut down, and in the fighting the trappers showed what they truly are. Whatever they had promised the Alliance, the worgen of Silverbrook are now enemies to both armies.', 'quest 12310 description and reward text; quest 12412 description and reward text (what''s this nonsense about worgen?); smart_scripts 27546 (Worgen Transform); quest 12413 description (Krenna sends her men against them)'),
(39428, 1, 0, 255, 'The trail led to the furbolgs. For thousands of years the tribes of the hills lived in peace; now they are crazed and bestial, and a dark, slimy substance drips from their dead. Their blood carries the very same taint as the ooze of Vordrassil.', 'quests 12229, 12246 descriptions and reward text'),
(39428, 2, 0, 255, 'Ursoc''s children told the rest. Their father, the bear god Ursoc, gave his life in the War of the Ancients, and for centuries the furbolgs who worshipped him sought a way to bring him back. At last they grew a sapling of Vordrassil and used its magic to raise him. Ursoc returned, but not as he had been: whatever evil drove the ancient druids to tear the tree down took root in the sapling too, and turned the god and his furbolgs into creatures filled with bloodlust.', 'npc_text 12793, 12794, 12796 (Orsonn); npc_text 12797, 12798 (Kodian); quests 12231, 12247 descriptions and reward text'),
(39428, 3, 0, 255, 'The sapling in Grizzlemaw was burned and its ashes purified. With Tur Ragepaw, a Timbermaw furbolg come north in hope of saving him, Ursoc was brought down at his den and the ashes laid upon him. His spirit rose free and gave thanks. The druids of old were wise, he said, for Vordrassil''s roots reach into the dwelling of an ancient evil, an old god, Yogg-Saron, the beast with a thousand maws, whose evil reaches beyond the tree. The druid who purified the ashes was left pale and staring when it was done.', 'quests 12248, 12241 descriptions (burn the sapling, purify the ashes); quests 12249, 12236 descriptions and reward text (the druid looks pale); npc_text 12785, 12787, 12798 (Tur Ragepaw, Timbermaw from the south); creature_text 27328 group 3, 27373 groups 0-1 (Spirit of Ursoc); smart_scripts 26633 (spell 48549 summons Spirit of Ursoc); npc_text 13032 (Thayreen: cleansing the corruption took its toll)'),
(39429, 1, 0, 255, 'Drakuru speaks of a legendary set of artifacts, lost for thousands of years, made to render Drak''Tharon Keep impervious; most think them myth. He was captured while reading the hieroglyphs that would reveal one, so his elixir, mixed with frozen mojo taken from his own brothers at the Ruins of Drak''Zin, called his image to a brazier there to finish reading. He hated to see his brothers fall, he said, but it was for the greater good.', 'quest 11990 description (the elixir); quest 11991 description and reward text'),
(39429, 2, 0, 255, 'The first artifact was the Eye of the Prophets, a ruby eye of the great stone head atop the ziggurat of Zeb''Halak. Its price was the mojo of Warlord Zim''bo, who in Drakuru''s words swore the blood oath to defend Drak''Tharon and failed. Drakuru called the eye more precious than he had hoped, sure to bring his people hope in these dark times.', 'quest 12007 description and reward text'),
(39429, 3, 0, 255, 'Through the eye Drakuru saw the Heart of the Ancients beside a dead goblin in the uppermost chamber of the Blue Sky Logging Grounds, unearthed by the goblin''s digging and overlooked in the chaos. He watched it found, and had it brought to his brazier at Drak''atal Passage with mojo taken from the passage''s desperate defenders. Soon, he promised, he would avenge his brothers by cleansing Drak''Tharon, and its greatest treasure would be the reward.', 'quest 12042 description and reward text; quest 12802 description and reward text'),
(39429, 4, 0, 255, 'With the eye on his brow and the heart on his chest, Drakuru could read the Drakkari Tablets, older than anyone knows, which lay deep in the crypt at Drakil''jin. They were taken, the ruins'' oracles and protectors gave up their sacred mojo to summon him, and Drakuru declared that he now had every component he needed to perform the cleansing ritual.', 'quest 12068 description and reward text'),
(39430, 1, 0, 255, 'The jars from the crypt held entrails, and in them Kraz sensed a corruption filling the ancient spirits with angst and barring their rest. Ending it demanded a great sacrifice. With the mallet of Drak''aguul, the gongs before the ruins were struck, the spirit of the one who corrupts the place answered and delivered the seeker into death, and on the other side the spirit Gan''jo greeted the one whose coming had been foretold.', 'quests 12116, 12120 reward text; quest 12121 description and reward text; creature_text 26902 (How dare you summon me without an offering)'),
(39430, 2, 0, 255, 'The Drakkari have become a lost people, Gan''jo said, fierce and savage, while their dead suffer through no fault of their own. The ancient spirits were laid to sleep with the Snow of Eternal Slumber, and from what remained of them Kraz made spirit dust for the sacred offering in the crypt. Brought to the gongs, it called up Warlord Jin''arrak, the corrupted warlord, who took the offering gladly and was undone by it, freeing many tormented souls from eons of misery.', 'quest 12137 description and reward text; quest 12152 description and reward text; creature_text 27199 groups 0-1'),
(39431, 1, 0, 255, 'Those who knew something of the iron dwarves told the same tale: they serve a master named Loken, and the war they are preparing is meant for the stone giants. What Loken has been ordering the iron dwarves of Dun Argol to do is still to be learned.', 'quest 12180 reward text (a war against stone giants); creature_text 27115 (Varana: serving their master Loken); quest 12204 reward text (the mastermind behind the iron dwarves); creature_text 26420 (Gavrock: Loken commands the sons of iron against the stone giants); creature_text 26484 group 1 (Hugh Glass knows Loken)'),
(39431, 2, 0, 255, 'Disguised as an iron overseer, a spy stood at the pedestal where Dun Argol''s thane and overseers receive their orders and overheard Loken''s message. He means to set the titans'' creations against one another, the sons of stone against the sons of iron, in a war for the ancient titan city of Ulduar.', 'quests 12185, 12203 descriptions and reward text'),
(39431, 3, 0, 255, 'Rather than storm Dun Argol, both camps turned its own works against it. A war golem built from stolen blueprints and parts, powered by cells taken from its rune-smiths and charged from the lightning sentries, was driven into the stronghold. It disabled the Anvil, the construct whose protection shielded Iron Thane Furyhammer, and the thane fell.', 'quests 12129-12131, 12138, 12153 (Alliance) and 12165, 12196-12199 (Horde) descriptions and reward text'),
(39431, 4, 0, 255, 'Prospector Rokar, the wounded dwarf the taunka had pressed into building the golem, expected his freedom. Tormak the Scarred could neither let him go nor take him along, but Vor''takh stayed the chieftain''s blade: the dwarf might help them track down Brann Bronzebeard. Rokar swore he would never help capture Brann, until Vor''takh reminded him of the price, and Tormak let him live, for as long as he proves useful.', 'smart_scripts 27221 event 1 (actionlist 2722101 on 12199''s reward); creature_text 27221 groups 4-6, 27227 groups 1-2, 26666 groups 0-3; quest 12199 reward text'),
(39432, 1, 0, 255, 'Brann''s last entry told how he used a runic keystone to light up the important runes on a plate he found in Thor Modan, and how the iron dwarf defenders seized the keystone from him, shattered it and divided the pieces among themselves.', 'quest 11988 description; quest 11986 reward text'),
(39432, 2, 0, 255, 'Read with a keystone, the three rune plates of Thor Modan gave up the words Brann had followed: ''The cradle of stone and iron.'' ''Ulduar nestled in the storm.'' Brann seems to believe he has found a new titan city, and those who read his notes mean to follow him.', 'quests 11993, 12058 descriptions and reward text');
